//! Thin Tauri shell for the installed Meshrix Entry product.
//!
//! This binary owns the desktop window, launches or attaches to the Node
//! profile owner, and hands the authenticated bridge to the webview. A probe
//! that attached to a pre-existing owner is never allowed to stop that owner.
//!
//! All product logic — custody, pairing, recovery, sessions, MCP — lives in
//! the Node service (`src/main/` → bundled `entry-service.mjs`). Rust holds
//! no secrets beyond the current owner's bearer token and performs no business
//! decisions. The token is generated by the canonical Node owner and delivered
//! to the webview only through `meshrix_bridge_config`
//! command — never placed in a URL, log line or window title.

#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

use std::fs;
use std::io::{BufRead, BufReader};
use std::path::PathBuf;
use std::process::Stdio;
use std::sync::{Arc, Condvar, Mutex};

use serde::Serialize;
use tauri::{Manager, RunEvent};
use tauri_plugin_shell::process::{CommandChild, CommandEvent};
use tauri_plugin_shell::ShellExt;

/// The shell hands this to the service through env; every route demands it.
const TOKEN_ENV: &str = "MESHRIX_ENTRY_SERVICE_TOKEN";
const DATA_DIR_ENV: &str = "MESHRIX_ENTRY_DATA_DIR";
const APP_IDENTIFIER: &str = "com.meshrix.entry";
const SERVICE_CONFIG_ENV: &str = "MESHRIX_ENTRY_SERVICE_CONFIG_PATH";
const APP_VERSION_ENV: &str = "MESHRIX_ENTRY_APP_VERSION";
const APP_EXE_ENV: &str = "MESHRIX_ENTRY_APP_EXE";
const ACCOUNT_ORIGIN_ENV: &str = "MESHRIX_ACCOUNT_ORIGIN";
/// Dev override: path to a runnable `entry-service.mjs` when no bundled
/// resource exists (plain `node` + `npm run build:service` flow).
const SERVICE_ENTRY_ENV: &str = "MESHRIX_ENTRY_SERVICE_ENTRY";
/// Dev/ops override: explicit Node runtime path.
const NODE_ENV_VAR: &str = "MESHRIX_ENTRY_SERVICE_NODE";

enum ServiceChild {
    Sidecar(CommandChild),
    Process(Arc<Mutex<std::process::Child>>),
}

impl ServiceChild {
    /// `CommandChild::kill` consumes its receiver — kill consumes the child too.
    fn kill(self) {
        match self {
            ServiceChild::Sidecar(child) => {
                let _ = child.kill();
            }
            ServiceChild::Process(child) => {
                let _ = child.lock().unwrap().kill();
            }
        }
    }
}

/// Authenticated loopback bridge returned by either the canonical service
/// owner or the short-lived GUI attach probe, plus the child handle.
struct BridgeState {
    launch: Arc<BridgeLaunchSignal>,
    child: Mutex<Option<ServiceChild>>,
    account_origin: Option<String>,
}

#[derive(Clone, Serialize)]
struct BridgeConfig {
    port: u16,
    token: String,
}

#[derive(Clone)]
struct BridgeReady {
    config: BridgeConfig,
    attached: bool,
}

enum BridgeLaunchState {
    WaitingForOwner,
    Ready(BridgeReady),
    Failed(String),
}

struct BridgeLaunchSignal {
    state: Mutex<BridgeLaunchState>,
    changed: Condvar,
}

const MAX_BRIDGE_FRAME_BYTES: usize = 4096;

fn accept_bridge_bytes(buffer: &mut Vec<u8>, chunk: &[u8], launch: &BridgeLaunchSignal) {
    buffer.extend_from_slice(chunk);
    while let Some(newline) = buffer.iter().position(|byte| *byte == b'\n') {
        let frame: Vec<u8> = buffer.drain(..=newline).collect();
        if frame.len() <= MAX_BRIDGE_FRAME_BYTES {
            if let Some(ready) = parse_bridge_config(&frame[..frame.len() - 1]) {
                launch.ready(ready);
            }
        }
    }
    if buffer.len() > MAX_BRIDGE_FRAME_BYTES {
        buffer.clear();
    }
}

impl BridgeLaunchSignal {
    fn new() -> Self {
        Self {
            state: Mutex::new(BridgeLaunchState::WaitingForOwner),
            changed: Condvar::new(),
        }
    }

    fn ready(&self, ready: BridgeReady) {
        let mut state = self.state.lock().unwrap();
        if matches!(*state, BridgeLaunchState::WaitingForOwner) {
            *state = BridgeLaunchState::Ready(ready);
            self.changed.notify_all();
        }
    }

    fn failed(&self, message: &str) {
        let mut state = self.state.lock().unwrap();
        let can_fail = match &*state {
            BridgeLaunchState::WaitingForOwner => true,
            BridgeLaunchState::Ready(ready) => !ready.attached,
            BridgeLaunchState::Failed(_) => false,
        };
        if can_fail {
            *state = BridgeLaunchState::Failed(message.to_string());
            self.changed.notify_all();
        }
    }

    fn is_attached(&self) -> bool {
        matches!(*self.state.lock().unwrap(), BridgeLaunchState::Ready(BridgeReady { attached: true, .. }))
    }

    fn wait(&self) -> Result<BridgeConfig, String> {
        let mut state = self.state.lock().unwrap();
        loop {
            match &*state {
                BridgeLaunchState::WaitingForOwner => state = self.changed.wait(state).unwrap(),
                BridgeLaunchState::Ready(ready) => return Ok(ready.config.clone()),
                BridgeLaunchState::Failed(message) => return Err(message.clone()),
            }
        }
    }
}

/// The webview calls this once on load to learn where the trusted service
/// listens. It waits until the launcher attaches or reports a concrete failure.
#[tauri::command]
async fn meshrix_bridge_config(state: tauri::State<'_, BridgeState>) -> Result<BridgeConfig, String> {
    let launch = Arc::clone(&state.launch);
    tauri::async_runtime::spawn_blocking(move || launch.wait())
        .await
        .map_err(|_| "The Meshrix service launcher failed before it could attach.".to_string())?
}

/// Open only the release-configured account origin. Renderer input is limited
/// to an opaque transaction id; it can never supply a URL or redirect target.
#[tauri::command]
fn meshrix_open_account_page(
    app: tauri::AppHandle,
    state: tauri::State<'_, BridgeState>,
    transaction_id: Option<String>,
) -> Result<(), String> {
    let origin = state.account_origin.as_deref().ok_or_else(|| {
        "the installed Meshrix account service origin is unavailable".to_string()
    })?;
    let url = match transaction_id {
        Some(id) if valid_transaction_id(&id) => format!("{origin}/account?transactionId={id}"),
        Some(_) => return Err("the account transaction reference is invalid".to_string()),
        None => format!("{origin}/account"),
    };
    app.shell().open(url, None).map_err(|_| "the system browser could not be opened".to_string())
}

/// Explicit quit is separate from closing the window so the profile owner and
/// healthy ACP work continue while the window is merely minimized.
#[tauri::command]
fn meshrix_quit(app: tauri::AppHandle) {
    app.exit(0);
}

fn valid_transaction_id(value: &str) -> bool {
    (2..=127).contains(&value.len())
        && value.bytes().all(|byte| byte.is_ascii_alphanumeric() || b"._:-".contains(&byte))
        && value.as_bytes()[0].is_ascii_alphanumeric()
}

/// Keep the account origin a bare HTTPS origin so no environment-controlled
/// path, credentials, query, or fragment can become part of the browser URL.
fn normalize_account_origin(value: &str) -> Option<String> {
    let authority = value.strip_prefix("https://")?;
    if authority.is_empty() || authority.bytes().any(|byte| b"/?@#\\%".contains(&byte)) {
        return None;
    }
    let (host, port) = match authority.rsplit_once(':') {
        Some((host, port)) if !host.contains(':') => (host, Some(port)),
        Some(_) => return None,
        None => (authority, None),
    };
    let host_ok = !host.is_empty()
        && host.bytes().all(|byte| byte.is_ascii_alphanumeric() || byte == b'.' || byte == b'-')
        && host.as_bytes()[0].is_ascii_alphanumeric()
        && host.as_bytes()[host.len() - 1].is_ascii_alphanumeric();
    if !host_ok {
        return None;
    }
    if let Some(port) = port {
        let number = port.parse::<u16>().ok()?;
        if number == 0 || port.is_empty() {
            return None;
        }
        Some(format!("https://{host}:{number}"))
    } else {
        Some(format!("https://{host}"))
    }
}

/// Parse the private child-pipe bridge handoff. It is never written to logs.
fn parse_bridge_config(line: &[u8]) -> Option<BridgeReady> {
    let value: serde_json::Value = serde_json::from_slice(line).ok()?;
    if value.get("event")?.as_str()? != "entry_gui_bridge_ready" {
        return None;
    }
    let port = value
        .get("port")?
        .as_u64()
        .and_then(|p| u16::try_from(p).ok())
        .filter(|p| *p > 0)?;
    let token = value.get("token")?.as_str()?.to_string();
    if token.len() < 32 || !token.bytes().all(|byte| byte.is_ascii_alphanumeric() || b"-_".contains(&byte)) {
        return None;
    }
    let attached = value.get("attached")?.as_bool()?;
    Some(BridgeReady { config: BridgeConfig { port, token }, attached })
}

/// `service/entry-service.mjs` under the installed resource dir
/// (Contents/Resources on macOS, the install dir on Windows/Linux).
fn installed_service_entry() -> Option<PathBuf> {
    let exe_dir = std::env::current_exe().ok()?.parent()?.to_path_buf();
    let candidates = [
        exe_dir.join("service").join("entry-service.mjs"),
        exe_dir
            .join("..")
            .join("Resources")
            .join("service")
            .join("entry-service.mjs"),
        exe_dir
            .join("..")
            .join("resources")
            .join("service")
            .join("entry-service.mjs"),
    ];
    candidates.into_iter().find(|p| p.is_file())
}

/// The release-owned account and relay origins shipped beside the service.
/// The service and `--mcp-stdio` attachment receive this same artifact path.
fn installed_service_config() -> Option<PathBuf> {
    let exe_dir = std::env::current_exe().ok()?.parent()?.to_path_buf();
    let candidates = [
        exe_dir.join("service").join("service-config.json"),
        exe_dir
            .join("..")
            .join("Resources")
            .join("service")
            .join("service-config.json"),
        exe_dir
            .join("..")
            .join("resources")
            .join("service")
            .join("service-config.json"),
    ];
    candidates.into_iter().find(|path| path.is_file())
}

fn service_config_path() -> Option<PathBuf> {
    std::env::var(SERVICE_CONFIG_ENV)
        .ok()
        .map(PathBuf::from)
        .filter(|path| path.is_file())
        .or_else(installed_service_config)
}

#[derive(serde::Deserialize)]
struct ReleaseServiceConfig {
    #[serde(rename = "schemaVersion")]
    schema_version: String,
    #[serde(rename = "accountOrigin")]
    account_origin: String,
}

/// The packaged service artifact is the shared source for Rust browser links
/// and Node account/relay clients. Environment is only a development fallback
/// when no artifact exists; an invalid artifact never falls back to a second
/// source of truth.
fn configured_account_origin() -> Option<String> {
    if let Some(path) = service_config_path() {
        let bytes = fs::read(path).ok()?;
        let config: ReleaseServiceConfig = serde_json::from_slice(&bytes).ok()?;
        if config.schema_version != "meshrix-entry-service-config-1" {
            return None;
        }
        return normalize_account_origin(&config.account_origin);
    }
    std::env::var(ACCOUNT_ORIGIN_ENV).ok().and_then(|value| normalize_account_origin(&value))
}

/// Where the runnable service bundle lives: bundled resource first, then a
/// dev checkout layout (`apps/entry-gui/dist/service/entry-service.mjs`).
fn service_entry_path() -> Option<PathBuf> {
    if let Ok(custom) = std::env::var(SERVICE_ENTRY_ENV) {
        let path = PathBuf::from(custom);
        if path.is_file() {
            return Some(path);
        }
    }
    installed_service_entry().or_else(|| {
        let dev = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("dist")
            .join("service")
            .join("entry-service.mjs");
        dev.is_file().then_some(dev)
    })
}

/// The Node runtime: `MESHRIX_ENTRY_SERVICE_NODE` override → the bundled
/// sidecar (`<exe dir>/node`, where the bundler places `externalBin`) → a
/// `binaries/` subdir copy (dev staging) → `node` on PATH.
fn node_command() -> PathBuf {
    if let Ok(custom) = std::env::var(NODE_ENV_VAR) {
        let path = PathBuf::from(custom);
        if path.is_file() {
            return path;
        }
    }
    if let Ok(exe) = std::env::current_exe() {
        if let Some(dir) = exe.parent() {
            let name = if cfg!(windows) { "node.exe" } else { "node" };
            for bundled in [dir.join(name), dir.join("binaries").join(name)] {
                if bundled.is_file() {
                    return bundled;
                }
            }
        }
    }
    PathBuf::from(if cfg!(windows) { "node.exe" } else { "node" })
}

/// Append the product-owned data directory to Tauri's app-specific data path.
fn entry_data_dir(app_data_dir: Option<PathBuf>) -> Result<PathBuf, &'static str> {
    app_data_dir.map(|path| path.join("entry-data"))
        .ok_or("durable application data storage is unavailable")
}

/// Resolve the Node `--mcp-stdio` path from the platform data root.
fn standalone_data_dir_from(platform_data_dir: Option<PathBuf>) -> Result<PathBuf, &'static str> {
    entry_data_dir(platform_data_dir.map(|path| path.join(APP_IDENTIFIER)))
}

fn standalone_data_dir() -> Result<PathBuf, &'static str> {
    standalone_data_dir_from(dirs::data_dir())
}

fn product_data_dir_from(
    tauri_app_data_dir: Option<PathBuf>,
    platform_data_dir: Option<PathBuf>,
) -> Result<PathBuf, &'static str> {
    match tauri_app_data_dir {
        Some(path) => entry_data_dir(Some(path)),
        None => standalone_data_dir_from(platform_data_dir),
    }
}

fn product_data_dir(app: &tauri::App) -> Result<PathBuf, &'static str> {
    product_data_dir_from(app.path().app_data_dir().ok(), dirs::data_dir())
}

fn service_env_vars(data_dir: PathBuf, token: Option<&str>) -> Vec<(String, String)> {
    let mut vars = vec![
        (DATA_DIR_ENV.to_string(), data_dir.to_string_lossy().to_string()),
        (APP_VERSION_ENV.to_string(), env!("CARGO_PKG_VERSION").to_string()),
    ];
    if let Some(token) = token {
        vars.push((TOKEN_ENV.to_string(), token.to_string()));
    }
    if let Some(path) = service_config_path() {
        vars.push((SERVICE_CONFIG_ENV.to_string(), path.to_string_lossy().to_string()));
    }
    if let Ok(origin) = std::env::var(ACCOUNT_ORIGIN_ENV) {
        vars.push((ACCOUNT_ORIGIN_ENV.to_string(), origin));
    }
    if let Ok(exe) = std::env::current_exe() {
        vars.push((APP_EXE_ENV.to_string(), exe.to_string_lossy().to_string()));
    }
    vars
}

/// Spawn the backend sidecar via tauri-plugin-shell — `sidecar("node")`
/// resolves `<exe dir>/node`, where the bundler and `tauri dev` place the
/// `binaries/node-<triple>` externalBin. Falls back to a PATH `node` +
/// workspace service bundle when no vendored binary exists (dev without
/// `src-tauri/binaries/` populated).
fn spawn_service(
    app: &tauri::App,
    launch: Arc<BridgeLaunchSignal>,
) -> Result<ServiceChild, String> {
    let entry = service_entry_path().ok_or_else(|| {
        "entry service bundle not found (expected dist/service/entry-service.mjs or a packaged resource)"
            .to_string()
    })?;
    let envs = service_env_vars(product_data_dir(app)?, None);
    let entry_arg = entry.to_string_lossy().to_string();

    if let Ok(command) = app.shell().sidecar("node") {
        match command.args(vec![entry_arg.clone(), "--gui-launch".to_string()]).envs(envs.clone()).spawn() {
            Ok((mut rx, child)) => {
                let launch_events = Arc::clone(&launch);
                tauri::async_runtime::spawn(async move {
                    let mut frame = Vec::new();
                    while let Some(event) = rx.recv().await {
                        match event {
                            CommandEvent::Stdout(bytes) => accept_bridge_bytes(&mut frame, bytes.as_ref(), &launch_events),
                            CommandEvent::Terminated(_) => {
                                if !launch_events.is_attached() {
                                    launch_events.failed("The Meshrix service stopped before it could attach.");
                                }
                                break;
                            }
                            _ => {}
                        }
                    }
                    if !launch_events.is_attached() {
                        launch_events.failed("The Meshrix service launcher ended before it could attach.");
                    }
                });
                return Ok(ServiceChild::Sidecar(child));
            }
            Err(_) => {
                eprintln!("entry-gui shell: packaged sidecar could not start; trying the development service");
            }
        }
    }

    // Dev fallback: a system node + the workspace-built service bundle.
    let mut command = std::process::Command::new(node_command());
    command
        .arg(&entry)
        .arg("--gui-launch")
        .envs(envs)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .stdin(Stdio::null());
    let child = command
        .spawn()
        .map_err(|_| "failed to spawn the entry service sidecar".to_string())?;
    let child = Arc::new(Mutex::new(child));
    let stdout = child.lock().unwrap().stdout
        .take()
        .ok_or_else(|| "sidecar stdout was not piped".to_string())?;
    let launch_events = Arc::clone(&launch);
    let child_wait = Arc::clone(&child);
    std::thread::spawn(move || {
        for line in BufReader::new(stdout).lines() {
            match line {
                Ok(line) => {
                    if let Some(ready) = parse_bridge_config(line.as_bytes()) {
                        launch_events.ready(ready);
                    }
                }
                Err(_) => break,
            }
        }
        let _ = child_wait.lock().unwrap().wait();
        if !launch_events.is_attached() {
            launch_events.failed("The Meshrix service exited before the window could attach.");
        }
    });
    Ok(ServiceChild::Process(child))
}

/// `--mcp-stdio`: the app binary forwards straight onto the service — this is
/// what the emitted `mcpServers` snippet invokes. Stdio is inherited so the
/// MCP client's framed JSON-RPC reaches the service untouched.
fn run_mcp_stdio_forward() -> ! {
    let entry = service_entry_path().unwrap_or_else(|| {
        eprintln!("meshrix-entry: entry service bundle not found for --mcp-stdio");
        std::process::exit(2);
    });
    let data_dir = match standalone_data_dir() {
        Ok(path) => path,
        Err(_) => {
            eprintln!("meshrix-entry: durable application data storage is unavailable");
            std::process::exit(2);
        }
    };
    let status = std::process::Command::new(node_command())
        .arg(entry)
        .arg("--mcp-stdio")
        // Same data-dir convention as the GUI sidecar — without it the stdio
        // face reads an empty sibling dir and every call is endpoint_unreachable.
        .envs(service_env_vars(data_dir, None))
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status();
    match status {
        Ok(status) => std::process::exit(status.code().unwrap_or(1)),
        Err(error) => {
            eprintln!("meshrix-entry: could not launch the entry service ({error})");
            std::process::exit(1);
        }
    }
}

fn main() {
    if std::env::args().any(|arg| arg == "--mcp-stdio") {
        run_mcp_stdio_forward();
    }

    let launch = Arc::new(BridgeLaunchSignal::new());

    tauri::Builder::default()
        .plugin(tauri_plugin_shell::init())
        .invoke_handler(tauri::generate_handler![meshrix_bridge_config, meshrix_open_account_page, meshrix_quit])
        .setup({
            let launch = Arc::clone(&launch);
            move |app| {
                let child = match spawn_service(app, Arc::clone(&launch)) {
                    Ok(child) => Some(child),
                    Err(message) => {
                        launch.failed(&message);
                        None
                    }
                };
                app.manage(BridgeState {
                    launch,
                    child: Mutex::new(child),
                    account_origin: configured_account_origin(),
                });
                Ok(())
            }
        })
        .build(tauri::generate_context!())
        .expect("error while building the Meshrix Entry shell")
        .run(|handle, event| match event {
            RunEvent::WindowEvent {
                label,
                event: tauri::WindowEvent::CloseRequested { api, .. },
                ..
            } => {
                api.prevent_close();
                if let Some(window) = handle.get_webview_window(&label) {
                    let _ = window.minimize();
                }
            }
            RunEvent::WindowEvent {
                event: tauri::WindowEvent::Destroyed,
                ..
            } => {
                // The profile service is process-owned, not window-owned.
            }
            RunEvent::Exit => {
                if let Some(state) = handle.try_state::<BridgeState>() {
                    let attached = state.launch.is_attached();
                    if let Some(child) = state.child.lock().unwrap().take() {
                        if !attached {
                            child.kill();
                        }
                    }
                }
            }
            _ => {}
        });
}

#[cfg(test)]
mod tests {
    use super::{entry_data_dir, product_data_dir_from, standalone_data_dir_from, BridgeLaunchSignal};
    use std::path::PathBuf;

    #[test]
    fn missing_durable_storage_does_not_redirect_profile_to_temporary_storage() {
        assert!(entry_data_dir(None).is_err());
        assert!(product_data_dir_from(None, None).is_err());
    }

    #[test]
    fn gui_and_standalone_entry_points_resolve_the_same_application_data_directory() {
        let platform_data = PathBuf::from("/synthetic-platform-data");
        let tauri_app_data = platform_data.join("com.meshrix.entry");
        let gui = product_data_dir_from(Some(tauri_app_data), Some(platform_data.clone())).unwrap();
        let mcp = standalone_data_dir_from(Some(platform_data)).unwrap();
        assert_eq!(gui, PathBuf::from("/synthetic-platform-data/com.meshrix.entry/entry-data"));
        assert_eq!(gui, mcp);
    }

    #[test]
    fn startup_failure_is_available_to_the_renderer_bridge() {
        let launch = BridgeLaunchSignal::new();
        launch.failed("durable application data storage is unavailable");
        assert_eq!(
            launch.wait().err().as_deref(),
            Some("durable application data storage is unavailable")
        );
    }
}
